package org.apache.commons.math.linear;

import java.io.*;
import java.io.Serializable;
import java.math.*;
import java.util.*;
import org.apache.commons.math.exception.MathArithmeticException;
import org.apache.commons.math.exception.util.LocalizedFormats;
import org.apache.commons.math.util.FastMath;
import org.apache.commons.math.util.OpenIntToDoubleHashMap.Iterator;
import org.apache.commons.math.util.OpenIntToDoubleHashMap;
import org.junit.*;
import org.junit.Assert;
import org.junit.Test;
import static org.junit.Assert.*;

/**
 * Unit tests for OpenMapRealVector#ebeDivide
 */
public class OpenMapRealVector_ebeDivide_TriageGen2Test {

    private static final double EPSILON = 1e-10;

    @Test
    public void testEbeDivideWithStandardValues() {
        // Setup: Create a sparse vector (this) and a dense vector (v)
        // this: [10.0, 0.0, 20.0]
        // v:    [2.0, 5.0, 4.0]
        // result should be: [10/2, 20/4] = [5.0, 0.0, 5.0]
        // Note: ebeDivide only iterates over non-zero entries of 'this'

        OpenMapRealVector thisVector = new OpenMapRealVector(3);
        thisVector.setEntry(0, 10.0);
        thisVector.setEntry(2, 20.0);

        double[] vData = {2.0, 5.0, 4.0};
        RealVector v = new ArrayRealVector(vData);

        OpenMapRealVector result = thisVector.ebeDivide(v);

        Assert.assertEquals("Dimension mismatch", 3, result.getDimension());
        Assert.assertEquals("Index 0 failed", 5.0, result.getEntry(0), EPSILON);
        Assert.assertEquals("Index 1 (sparse) failed", 0.0, result.getEntry(1), EPSILON);
        Assert.assertEquals("Index 2 failed", 5.0, result.getEntry(2), EPSILON);
    }

    @Test
    public void testEbeDivideWithAllZeros() {
        OpenMapRealVector thisVector = new OpenMapRealVector(3);
        double[] vData = {1.0, 2.0, 3.0};
        RealVector v = new ArrayRealVector(vData);

        OpenMapRealVector result = thisVector.ebeDivide(v);

        Assert.assertEquals(3, result.getDimension());
        Assert.assertEquals(0.0, result.getEntry(0), EPSILON);
        Assert.assertEquals(0.0, result.getEntry(1), EPSILON);
        Assert.assertEquals(0.0, result.getEntry(2), EPSILON);
    }

    @Test(expected = DimensionMismatchException.class)
    public void testEbeDivideDimensionMismatch() {
        // This should trigger checkVectorDimensions(v.getDimension())
        OpenMapRealVector thisVector = new OpenMapRealVector(3);
        thisVector.setEntry(0, 10.0);

        RealVector v = new ArrayRealVector(2); // Dimension 2 != 3
        v.setEntry(0, 2.0);
        v.setEntry(1, 2.0);

        thisVector.ebeDivide(v);
    }

    @Test
    public void testEbeDivideWithDivisionByZero() {
        // If v contains zero at an index where 'this' is non-zero, result should be Infinity
        OpenMapRealVector thisVector = new OpenMapRealVector(2);
        thisVector.setEntry(0, 10.0);
        thisVector.setEntry(1, 5.0);

        double[] vData = {0.0, 5.0};
        RealVector v = new ArrayRealVector(vData);

        OpenMapRealVector result = thisVector.ebeDivide(v);

        Assert.assertTrue("Result at index 0 should be Infinity", Double.isInfinite(result.getEntry(0)));
        Assert.assertEquals("Result at index 1 should be 1.0", 1.0, result.getEntry(1), EPSILON);
    }

    @Test
    public void testEbeDivideWithNegativeValues() {
        OpenMapRealVector thisVector = new OpenMapRealVector(2);
        thisVector.setEntry(0, -10.0);
        thisVector.setEntry(1, 10.0);

        double[] vData = {-2.0, 5.0};
        RealVector v = new ArrayRealVector(vData);

        OpenMapRealVector result = thisVector.ebeDivide(v);

        Assert.assertEquals("Negative division failed", 5.0, result.getEntry(0), EPSILON);
        Assert.assertEquals("Positive division failed", 2.0, result.getEntry(1), EPSILON);
    }

    @Test
    public void testEbeDivideLargeDimensionSparse() {
        // Test behavior with a larger dimension to ensure iterator works correctly
        int dim = 1000;
        OpenMapRealVector thisVector = new OpenMapRealVector(dim);
        thisVector.setEntry(500, 100.0);
        thisVector.setEntry(999, 50.0);

        double[] vData = new double[dim];
        for(int i=0; i<dim; i++) vData[i] = 1.0;
        RealVector v = new ArrayRealVector(vData);

        OpenMapRealVector result = thisVector.ebeDivide(v);

        Assert.assertEquals(50.0, result.getEntry(500), EPSILON);
        Assert.assertEquals(50.0, result.getEntry(999), EPSILON);
        Assert.assertEquals(0.0, result.getEntry(0), EPSILON);
    }
}
